const $=id=>document.getElementById(id), money=n=>'₹'+Math.round(n).toLocaleString('en-IN');
let saved=null,crashed=false;try{saved=JSON.parse(localStorage.getItem('honest-million-v1'));if(saved&&(!Number.isFinite(saved.monthly)||!Number.isFinite(saved.growth)||!Number.isFinite(saved.equity)||!Number.isFinite(saved.steady)))saved=null}catch{}
if(saved){$('monthly').value=saved.monthly;$('growth').value=saved.growth;$('buffer').checked=saved.buffer}
function simulate(monthly,growth){const rate=(.05+.04*growth/100)/12;let value=0,months=0,points=[0];while(value<1e6&&months<1200){value=value*(1+rate)+monthly;months++;points.push(value)}return{months,points,rate}}
function update(){let m=+$('monthly').value,g=+$('growth').value;const s=simulate(m,g);$('monthlyValue').textContent=money(m);$('leftover').textContent=money(8000-m);$('growthValue').textContent=g+'%';$('equityAmount').textContent=money(m*g/100);$('steadyAmount').textContent=money(m*(1-g/100));$('years').textContent=(s.months/12).toFixed(1);$('age').textContent='Around age '+Math.ceil(19+s.months/12)+', if these assumptions hold.';$('endAge').textContent='Age '+Math.ceil(19+s.months/12)+' · your goal';$('assumptions').textContent='Assumes '+(s.rate*1200).toFixed(1)+'% annual growth, fixed contributions, no fees or taxes. Real markets will not follow this smooth line.';$('inflation').textContent='With an illustrative 5% annual inflation rate, ₹10 lakh in '+(s.months/12).toFixed(1)+' years would buy roughly what '+money(1e6/Math.pow(1.05,s.months/12))+' buys today.';const d=s.points.map((v,i)=>(i?'L':'M')+(10+i/s.months*500).toFixed(1)+' '+(175-v/s.points.at(-1)*155).toFixed(1)).join(' ');$('line').setAttribute('d',d);$('area').setAttribute('d',d+'L510 185L10 185Z');$('bufferNote').textContent=$('buffer').checked?'Your safety net stays separate. Choose an amount you can sustain through ordinary months.':'Before investing, set aside accessible money for unexpected expenses. This is a preview until you’re ready.';if(crashed)showCrash()}
function persist(){try{localStorage.setItem('honest-million-v1',JSON.stringify(saved));return true}catch{return false}}
function journey(){let e=saved?.equity||0,s=saved?.steady||0,total=e+s;$('balance').textContent=money(total);$('growthHolding').textContent=money(e);$('steadyHolding').textContent=money(s);$('progressBar').style.width=Math.min(100,total/1e4)+'%';$('percent').textContent=(total/1e4).toFixed(1)+'% of the way';$('contribute').disabled=!saved;$('journeyText').textContent=saved?money(saved.monthly)+' / month · '+saved.growth+'% growth · '+saved.months+' practice months logged.':'Save a plan above to start your journey.'}
function showCrash(){const g=+$('growth').value,loss=100000*g/100*.3;$('stormAmount').textContent=money(100000-loss);$('scenarioTag').textContent='GROWTH PORTION −30%';$('stormTitle').textContent='Down '+money(loss)+'. Take a breath.';$('stormText').textContent='Your '+g+'% growth mix makes this a '+(g*.3).toFixed(0)+'% portfolio decline. Your goal may take longer. Recovery is uncertain; it does not arrive on a schedule.';$('stormLine').setAttribute('d','M0 60L55 40L105 48L155 19L205 25L255 70L310 90L355 82L400 88');$('stormLine').style.stroke='#b26242';$('stormActions').hidden=false;document.querySelector('.storm-card').classList.add('crashed');$('crash').innerHTML='Reset the scenario <span>↺</span>'}
$('crash').onclick=()=>{crashed=!crashed;$('response').textContent='';if(crashed)showCrash();else{$('stormAmount').textContent=money(100000);$('scenarioTag').textContent='BEFORE THE DROP';$('stormTitle').textContent='The plan includes imperfect years.';$('stormText').textContent='Press the button. We’ll drop the growth portion by 30% and hold the steady portion flat in this simplified scenario.';$('stormLine').setAttribute('d','M0 80L55 60L105 68L155 39L205 45L255 23L310 31L355 12L400 8');$('stormLine').style.stroke='';$('stormActions').hidden=true;document.querySelector('.storm-card').classList.remove('crashed');$('crash').innerHTML='Try a market drop <span>↘</span>'}};
document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>{$('response').textContent=b.dataset.response==='stay'?'Keeping the habit can make sense when your goal is far away, your buffer is intact and you can afford it. It does not guarantee recovery. Review the plan if your needs change.':'Pausing can protect money you need for essentials. Check your buffer and time horizon, then revisit the monthly amount above. A sustainable plan can change with your life.'});
['monthly','growth','buffer'].forEach(id=>$(id).addEventListener('input',update));$('save').onclick=()=>{saved={monthly:+$('monthly').value,growth:+$('growth').value,buffer:$('buffer').checked,equity:saved?.equity||0,steady:saved?.steady||0,months:saved?.months||0};$('saveStatus').textContent=persist()?'Practice plan saved on this device. Your check-in is ready below.':'Plan ready for this session; browser storage is unavailable.';journey()};$('contribute').onclick=()=>{if(!saved)return;saved.equity+=saved.monthly*saved.growth/100;saved.steady+=saved.monthly*(1-saved.growth/100);saved.months++;persist();journey()};$('reset').onclick=()=>{saved=null;try{localStorage.removeItem('honest-million-v1')}catch{}$('monthly').value=2000;$('growth').value=70;$('buffer').checked=false;$('saveStatus').textContent='Demo reset.';if(crashed)$('crash').click();update();journey()};update();journey();
